<?php use VazinCMS\Security; ?>
<section class="admin-title"><div><span class="eyebrow">راهنمای مدیر</span><h1>سئو، کیفیت محتوا و برنامهٔ انتشار</h1><p>این موارد پیشنهاد و اخطار مدیریتی‌اند؛ هیچ محتوا یا ادعایی به‌صورت خودکار حذف یا از انتشار منع نمی‌شود.</p></div><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="analyze_all"><button>تحلیل همهٔ محتوا</button></form></section>
<?php if($error):?><div class="alert error"><?=Security::e($error)?></div><?php endif;?><?php if($message):?><div class="alert success"><?=Security::e($message)?></div><?php endif;?>
<section class="metrics-grid"><div class="metric"><b><?=$summary['pages']?></b><span>کل محتوا</span></div><div class="metric"><b><?=$summary['analyzed']?></b><span>تحلیل‌شده</span></div><div class="metric"><b><?=$summary['average']?></b><span>میانگین امتیاز</span></div><div class="metric warning"><b><?=$summary['open']?></b><span>اخطار باز</span></div></section>
<section class="editor-card"><div class="card-head"><div><h2>برنامهٔ پیشنهادی انتشار</h2><p>فاصلهٔ پایه را مشخص کنید؛ مدیر می‌تواند هر پیشنهاد را بپذیرد یا کنار بگذارد.</p></div><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="save_cadence"><label>هر <input type="number" name="cadence_days" min="1" max="30" value="<?=$cadence?>" style="width:5rem"> روز</label><button>ذخیره</button></form></div><?php foreach($suggestions as $suggestion):?><article class="page-item"><div class="page-main"><strong><?=Security::e($suggestion['title'])?></strong><span><?=Security::e($suggestion['rationale'])?></span><code><?=Security::e($suggestion['suggested_at'])?></code><span class="status <?=Security::e($suggestion['status'])?>"><?=Security::e($suggestion['status'])?></span></div><?php if(in_array($suggestion['status'],['open','accepted'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="suggestion_status"><input type="hidden" name="id" value="<?=(int)$suggestion['id']?>"><button name="status" value="accepted">پذیرفتن</button><button class="button ghost" name="status" value="dismissed">رد</button><button class="button secondary" name="status" value="completed">انجام شد</button></form><?php endif;?></article><?php endforeach;?></section>
<section class="list-card"><div class="card-head"><div><h2>اخطارهای محتوایی</h2><p>اخطارهای پزشکی و تبلیغاتی صرفاً برای بازبینی مدیر ثبت می‌شوند.</p></div></div><?php foreach($advisories as $item):?><article class="page-item"><div class="page-main"><div><strong><?=Security::e($item['title'])?></strong> <span class="status <?=Security::e($item['severity'])?>"><?=Security::e($item['severity'])?></span></div><span><?=Security::e($item['message'])?></span><a href="/admin/pages?edit=<?=(int)$item['page_id']?>"><?=Security::e($item['page_title'])?></a><small><?=Security::e($item['category'].' · '.$item['status'])?></small></div><?php if(in_array($item['status'],['open','acknowledged'],true)):?><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="advisory_status"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button name="status" value="acknowledged">دیدم</button><button class="button secondary" name="status" value="resolved">اصلاح شد</button><button class="button ghost" name="status" value="ignored">نادیده گرفتن</button></form><?php endif;?></article><?php endforeach;?><?php if(!$advisories):?><div class="empty-state"><b>اخطاری ثبت نشده است</b><p>تحلیل همهٔ محتوا را اجرا کنید.</p></div><?php endif;?></section>
<section class="list-card"><div class="card-head"><div><h2>گزارش صفحه‌ها</h2><p>امتیاز برای اولویت‌بندی است، نه معیار قطعی کیفیت.</p></div></div><?php foreach($reports as $report):?><article class="page-item"><a class="page-main" href="/admin/pages?edit=<?=(int)$report['page_id']?>"><strong><?=Security::e($report['title'])?></strong><code>/<?=Security::e($report['locale'].'/page/'.$report['slug'])?></code><span class="status <?=$report['score']>=80?'published':($report['score']>=55?'warning':'failed')?>">امتیاز <?=(int)$report['score']?></span><small><?=Security::e($report['analyzed_at'])?></small></a></article><?php endforeach;?></section>
